import java.util.*;import java.math.BigInteger;
public class ChineseRemainderTheoremInverse {public static void main(String[] args){Scanner sc=new Scanner(System.in);System.out.print("Enter no. of equations: ");int n=sc.nextInt();long[] rem=new long[n],mod=new long[n];BigInteger N=BigInteger.ONE;for(int i=0;i<n;i++){System.out.print("Enter remainder: ");rem[i]=sc.nextLong();System.out.print("Enter modulus: ");mod[i]=sc.nextLong();if(mod[i]<=0){System.out.println("Moduli must be positive.");return;}N=N.multiply(BigInteger.valueOf(mod[i]));}BigInteger x=BigInteger.ZERO;for(int i=0;i<n;i++){BigInteger m=BigInteger.valueOf(mod[i]),Ni=N.divide(m);if(!Ni.gcd(m).equals(BigInteger.ONE)){System.out.println("Moduli must be pairwise coprime for this CRT method.");return;}BigInteger inverse=Ni.modInverse(m);x=x.add(BigInteger.valueOf(rem[i]).multiply(Ni).multiply(inverse));}System.out.println("Solution: "+x.mod(N));}}
